52	  onSaveNewMember,
53	}: Props) => {
54	  const { t } = useTranslation(undefined, {
55	    keyPrefix: "sheet.member-sheet",
56	  });
57	  const { removeMember, fetchMemberDetail, detailLoadedIds } = useMemberStore();
58	  const { refreshEvents, initialized: eventsInitialized } = useEventStore();
59	  const { refreshStories, initialized: storiesInitialized } = useStoryStore();
60	  const { refreshTasks, initialized: tasksInitialized } = useTaskStore();
61	  const restrictions = useTreeStore((s) => s.selectedTree?.restrictions);
62	  const tasksEnabled =
63	    useFeature("research_tasks") && !restrictions?.includes("tasks");
64	  const { refreshDocuments, initialized: documentsInitialized } =
65	    useDocumentStore();
66	  const { refreshGalleryImages, initialized: galleryInitialized } =
67	    useGalleryStore();
68	  const setMapFocus = useNavigationStore((s) => s.setMapFocus);
