110	      mode: isViewingEditMode ? "edit" : "view",
111	    });
112	  }, [
113	    activeTab,
114	    isNewMember,
115	    isOpen,
116	    isViewingEditMode,
117	    member?.id,
118	    savedSheetState?.memberId,
119	    setOpenSheet,
