263	              {isViewingEditMode
264	                ? t("edit-description")
265	                : t("detail-description")}
266	            </SheetDescription>
267	            {editors.length > 0 && (
268	              <div className="mt-1.5 flex items-center gap-1.5 text-xs font-medium text-amber-600 dark:text-amber-500">
269	                <Pencil className="size-3 shrink-0" />
270	                <span className="truncate">
271	                  {t("presence-editing", {
272	                    name: editors.map((e) => e.displayName).join(", "),
273	                  })}
274	                </span>
275	              </div>
276	            )}
277	          </div>
278	          {effectiveCanEdit && (
279	            <div className="absolute top-4 right-4">
280	              <Button
281	                variant="ghost"
